const updateTalkgroup = `-- name: UpdateTalkgroup :one
UPDATE talkgroups
SET
	name = COALESCE($1, name),
	alpha_tag = COALESCE($2, alpha_tag),
	tg_group = COALESCE($3, tg_group),
	frequency = COALESCE($4, frequency),
	metadata = COALESCE($5, metadata),
	tags = COALESCE($6, tags),
	alert = COALESCE($7, alert),
	alert_rules = COALESCE($8, alert_rules),
	weight = COALESCE($9, weight),
	learned = COALESCE($10, learned)
WHERE id = $11 OR (system_id = $12 AND tgid = $13)
RETURNING id, system_id, tgid, name, alpha_tag, tg_group, frequency, metadata, tags, alert, alert_rules, weight, learned, ignored
`

type UpdateTalkgroupParams struct {
	Name       *string            `json:"name"`
	AlphaTag   *string            `json:"alpha_tag"`
	TGGroup    *string            `json:"tg_group"`
	Frequency  *int32             `json:"frequency"`
	Metadata   jsontypes.Metadata `json:"metadata"`
	Tags       []string           `json:"tags"`
	Alert      *bool              `json:"alert"`
	AlertRules rules.AlertRules   `json:"alert_rules"`
	Weight     *float32           `json:"weight"`
	Learned    *bool              `json:"learned"`
	ID         *int32             `json:"id"`
	SystemID   *int32             `json:"system_id"`
	TGID       *int32             `json:"tgid"`
}

func (q *Queries) UpdateTalkgroup(ctx context.Context, arg UpdateTalkgroupParams) (Talkgroup, error) {
	row := q.db.QueryRow(ctx, updateTalkgroup,
		arg.Name,
		arg.AlphaTag,
		arg.TGGroup,
		arg.Frequency,
		arg.Metadata,
		arg.Tags,
		arg.Alert,
		arg.AlertRules,
		arg.Weight,
		arg.Learned,
		arg.ID,
		arg.SystemID,
		arg.TGID,
	)
	var i Talkgroup
	err := row.Scan(
		&i.ID,
		&i.SystemID,
		&i.TGID,
		&i.Name,
		&i.AlphaTag,
		&i.TGGroup,
		&i.Frequency,
		&i.Metadata,
		&i.Tags,
		&i.Alert,
		&i.AlertRules,
		&i.Weight,
		&i.Learned,
		&i.Ignored,
	)
	return i, err
}
